package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The rates for each grade on a sheet, each in force from its from-date (or from the beginning of
 * time without one). Setting a rate for a grade and from-date that already have one replaces it.
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromAsc(sheetId);
    }

    /** The grade's rate in force on a date: the one with the latest from-date on or before it. */
    @Transactional(readOnly = true)
    public Optional<Rate> inForce(String sheetId, String grade, LocalDate date) {
        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(rate -> rate.getFrom() == null || !rate.getFrom().isAfter(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())));
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, BigDecimal pct) {
        sheets.load(sheetId, user);
        BigDecimal scaled = pct.setScale(2, RoundingMode.UNNECESSARY);
        Rate rate = rates.findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> Objects.equals(r.getFrom(), from))
                .findFirst().orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, scaled));
        } else {
            rate.setRate(scaled);
        }
        List<String> fields = new ArrayList<>(List.of("grade=" + rate.getGrade(), "rate=" + rate.getRate().toPlainString()));
        if (from != null) {
            fields.add("from=" + from);
        }
        audit.change("RATE_SET", sheetId, user, fields.toArray(String[]::new));
        return rate;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one record for a change to a sheet: the event, then sheet=&lt;id&gt; and by=&lt;user&gt;, then
     * the fields, separated by single spaces. Inside a transaction the record is written only once
     * it commits, so a change that is refused or rolled back writes nothing.
     */
    public void change(String event, String sheetId, String user, String... fields) {
        StringBuilder entry = new StringBuilder(event).append(" sheet=").append(sheetId).append(" by=").append(user);
        for (String field : fields) {
            entry.append(' ').append(field);
        }
        String line = entry.toString();
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    record(line);
                }
            });
        } else {
            record(line);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
-- The rate for each grade on a sheet: a percent with two decimals. A grade has at most one rate;
-- a grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    rate     DECIMAL(5, 2) NOT NULL CHECK (rate >= 0),
    CONSTRAINT rate_sheet_grade UNIQUE (sheet_id, grade)
);
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a rate with
-- no from-date applies from the beginning of time. A grade has at most one rate per from-date
-- (including at most one without a from-date, which the service ensures).
ALTER TABLE rate DROP CONSTRAINT rate_sheet_grade;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_sheet_grade_from UNIQUE (sheet_id, grade, from_date);
-- Claims made by a person on a sheet, listed newest first (by id). The amount is 0.00 or more with
-- two decimals; the date defaults to the sheet's today; the note may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(500)   NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The due a claim had when it was settled (amount times its person's grade's rate, rounded half up
-- to cents), kept so later changes to rates do not alter it. Null for a claim that is not settled,
-- or that was settled while its grade had no rate.
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Claim, toCents } from './claims';
import { Grade } from './people';
import { Session } from './session';

export interface Rate {
  grade: Grade;
  /** yyyy-mm-dd the rate is in force from; null for a rate in force from the beginning of time. */
  from: string | null;
  /** A percent, always with two decimals, e.g. "12.50". */
  rate: string;
}

/** A rate the store accepts: a percent of 0 or more, below 1000, with at most two decimals. */
export const RATE = /^\d{1,3}(\.\d{1,2})?$/;

/**
 * Cents due on an amount in cents at a rate (a percent with two decimals): amount times rate
 * divided by 100, rounded half to even to whole cents. Exact, as the rate is taken in hundredths.
 */
export function dueCents(cents: number, rate: string): number {
  const product = BigInt(cents) * BigInt(toCents(rate));
  const whole = product / 10000n;
  const rest = product % 10000n;
  return Number(rest > 5000n || (rest === 5000n && whole % 2n === 1n) ? whole + 1n : whole);
}

/**
 * The rate among these in force on a date (yyyy-mm-dd): the one with the latest from-date on or
 * before it, a rate with no from-date applying from the beginning of time. Undefined when none applies.
 */
export function rateOn(rates: Rate[], date: string): string | undefined {
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.from !== null && r.from > date) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.rate;
}

// The rates for each grade on the active sheet, per from-date, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

